  ('Physics', 'Edexcel', 'gcse', '2', 'Motion and Forces', 'What is a typical human reaction time?', 'About 0.2–0.9 s.', 28),
  ('Physics', 'Edexcel', 'gcse', '2', 'Motion and Forces', 'What is terminal velocity?', 'The maximum constant velocity reached when the drag force equals the weight, so the resultant force is zero.', 29),
