  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'What are the dangers of ultraviolet?', 'Skin damage, premature ageing, sunburn, skin cancer and eye damage.', 11),
  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'What are the dangers of X-rays and gamma rays?', 'They are ionising radiation and can cause mutations and cancer.', 12),
