  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'Why are higher-frequency EM waves more dangerous?', 'They carry more energy and can ionise atoms.', 15),
  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'What is the law of reflection?', 'The angle of incidence equals the angle of reflection.', 16),
