  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'What does a diverging lens do?', 'It spreads parallel rays of light out, as if they came from a focal point.', 23),
  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'What is the focal length?', 'The distance from the centre of a lens to its principal focus.', 24),
  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'What is a black body?', 'An object that absorbs all radiation falling on it and is the best possible emitter.', 25),
  ('Physics', 'Edexcel', 'gcse', '5', 'Light and the Electromagnetic Spectrum', 'How does temperature affect the radiation emitted by an object?', 'Hotter objects emit more radiation at shorter wavelengths.', 26),
