  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is the atomic number?', 'The number of protons in the nucleus.', 4),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is the mass number?', 'The total number of protons and neutrons in the nucleus.', 5),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is an isotope?', 'Atoms of the same element with the same number of protons but different numbers of neutrons.', 6),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is radioactive decay?', 'The random process in which an unstable nucleus emits radiation to become more stable.', 7),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is an alpha particle?', 'Two protons and two neutrons (a helium nucleus).', 8),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is a beta-minus particle?', 'A fast-moving electron emitted from the nucleus when a neutron turns into a proton.', 9),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is a positron?', 'A particle with the same mass as an electron but a positive charge, emitted in beta-plus decay.', 10),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is gamma radiation?', 'High-frequency electromagnetic radiation emitted from the nucleus.', 11),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is the penetrating power of alpha, beta and gamma?', 'Alpha is stopped by paper, beta by a few mm of aluminium, gamma is reduced by thick lead or concrete.', 12),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is the ionising power of alpha, beta and gamma?', 'Alpha is highly ionising, beta moderately, gamma weakly.', 13),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What happens in alpha decay?', 'The mass number decreases by 4 and the atomic number decreases by 2.', 14),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What happens in beta-minus decay?', 'The mass number stays the same and the atomic number increases by 1.', 15),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What happens in gamma emission?', 'No change to mass number or atomic number; the nucleus loses energy.', 16),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is half-life?', 'The time taken for the number of radioactive nuclei (or activity) to halve.', 17),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is activity?', 'The rate at which a source decays, measured in becquerels (Bq).', 18),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'A sample has activity 800 Bq and half-life 2 hours. What is the activity after 6 hours?', 'Three half-lives: 800 → 400 → 200 → 100 Bq.', 19),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is background radiation?', 'Radiation that is always around us from natural and man-made sources.', 20),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'Name three sources of background radiation.', 'Radon gas, rocks, cosmic rays, food, and medical X-rays.', 21),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is irradiation?', 'Exposing an object to radiation; the object does not become radioactive.', 22),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is contamination?', 'When radioactive atoms get onto or into an object.', 23),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'How can workers be protected from radiation?', 'Shielding, keeping distance, limiting exposure time, and monitoring doses.', 24),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'How is radiation used in medicine?', 'Radiotherapy to kill cancer cells, tracers to diagnose problems, and sterilising equipment.', 25),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What did the plum pudding model suggest?', 'The atom was a ball of positive charge with electrons embedded in it.', 26),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What did the alpha scattering experiment show?', 'Most of the atom is empty space and there is a small, dense, positive nucleus.', 27),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'How did Bohr improve the atomic model?', 'He suggested electrons orbit the nucleus in fixed energy levels (shells).', 28),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What happens when an electron moves to a higher energy level?', 'It absorbs electromagnetic radiation.', 29),
  ('Physics', 'Edexcel', 'gcse', '6', 'Radioactivity', 'What is nuclear fission?', 'Splitting a large nucleus into smaller nuclei, releasing energy and neutrons.', 30),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is the solar system?', 'The Sun and everything that orbits it: planets, dwarf planets, moons, asteroids and comets.', 1),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What are the eight planets in order from the Sun?', 'Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune.', 2),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What keeps planets in orbit?', 'The gravitational force of the Sun.', 3),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is a moon?', 'A natural satellite that orbits a planet.', 4),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is an artificial satellite?', 'A man-made object placed in orbit around the Earth, e.g. for communication or weather monitoring.', 5),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'How does orbital speed change with distance?', 'Objects closer to the body they orbit must travel faster to stay in orbit.', 6),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What was the geocentric model?', 'The early model with the Earth at the centre of the universe.', 7),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is the heliocentric model?', 'The model with the Sun at the centre of the solar system.', 8),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What evidence supported the heliocentric model?', 'Galileo''s observations of Jupiter''s moons orbiting Jupiter and the phases of Venus.', 9),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'How is a star formed?', 'A cloud of gas and dust (nebula) collapses under gravity, heats up, and nuclear fusion begins.', 10),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is the life cycle of a star like the Sun?', 'Nebula → protostar → main sequence star → red giant → white dwarf.', 11),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is the life cycle of a massive star?', 'Nebula → protostar → main sequence → red supergiant → supernova → neutron star or black hole.', 12),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What keeps a main sequence star stable?', 'The outward pressure from fusion balances the inward force of gravity.', 13),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is a supernova?', 'The explosion of a massive star at the end of its life.', 14),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is a black hole?', 'A region where gravity is so strong that not even light can escape.', 15),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is red-shift?', 'The increase in wavelength of light from galaxies moving away from us.', 16),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What does red-shift tell us about the universe?', 'Distant galaxies are moving away from us, and more distant galaxies are moving away faster, so the universe is expanding.', 17),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is the Big Bang theory?', 'The theory that the universe began from a very small, hot, dense region and has been expanding ever since.', 18),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is the Steady State theory?', 'The theory that the universe has always existed and new matter is created as it expands.', 19),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is the cosmic microwave background (CMB)?', 'Radiation left over from the early universe, detected in all directions.', 20),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'Why does the CMB support the Big Bang theory?', 'It is predicted by the Big Bang and can''t be explained by the Steady State theory.', 21),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'How do we observe the universe?', 'Using telescopes that detect different parts of the EM spectrum.', 22),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'Why are some telescopes placed in space?', 'To avoid absorption and distortion of radiation by the Earth''s atmosphere.', 23),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is a galaxy?', 'A large group of billions of stars held together by gravity.', 24),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What galaxy is our solar system in?', 'The Milky Way.', 25),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is a light year?', 'The distance light travels in one year.', 26),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is nuclear fusion in stars?', 'Hydrogen nuclei join to form helium, releasing large amounts of energy.', 27),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'Where are heavy elements made?', 'In supernovae (elements heavier than iron) and in massive stars.', 28),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is a dwarf planet?', 'A body that orbits the Sun and is nearly round, but hasn''t cleared its orbit of other objects, e.g. Pluto.', 29),
  ('Physics', 'Edexcel', 'gcse', '7', 'Astronomy', 'What is a comet?', 'A ball of ice and dust in a highly elliptical orbit around the Sun.', 30),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is work done?', 'Energy transferred when a force moves an object: W = F × d.', 1),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is the unit of work done?', 'The joule (J).', 2),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'Calculate the work done when a 20 N force moves an object 5 m.', '20 × 5 = 100 J.', 3),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is power?', 'The rate of doing work (energy transferred per second): P = E/t.', 4),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'Calculate the power of a motor that transfers 600 J in 20 s.', '600 ÷ 20 = 30 W.', 5),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is 1 watt?', '1 joule of energy transferred per second.', 6),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'Why is work done against friction wasted?', 'It transfers energy to thermal stores, heating the surroundings.', 7),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What happens to energy when you push a box along the floor?', 'Work is done against friction, transferring energy to thermal energy.', 8),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What happens to energy when a car brakes?', 'Kinetic energy is transferred to thermal energy in the brakes.', 9),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'How is work done related to energy transfer?', 'Work done equals energy transferred.', 10),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is the relationship between power, work done and time?', 'Power = work done ÷ time.', 11),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'Two motors lift the same load to the same height. One does it faster. Which is more powerful?', 'The faster one, because it transfers the same energy in less time.', 12),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What are the energy transfers for a person climbing stairs?', 'Chemical energy in muscles is transferred to GPE and thermal energy.', 13),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What are the energy transfers in an electric kettle?', 'Electrical energy is transferred to the thermal store of the water (and some wasted to the surroundings).', 14),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What are the energy transfers in a car engine?', 'Chemical energy in fuel is transferred to kinetic energy and thermal energy (wasted).', 15),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What are the energy transfers in a battery-powered torch?', 'Chemical energy in the battery is transferred electrically to light and thermal energy.', 16),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is useful energy?', 'Energy transferred to the store you want.', 17),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is the efficiency of a device that wastes 40% of its energy?', '60%.', 18),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'How do you calculate useful output from efficiency?', 'Useful output = efficiency × total input.', 19),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is a closed system?', 'A system where no energy enters or leaves, so the total energy stays constant.', 20),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'How can the efficiency of a car be improved?', 'Streamlining to reduce air resistance, reducing friction, and using lighter materials.', 21),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'Why can no device be 100% efficient?', 'Some energy is always wasted, usually as thermal energy due to friction or resistance.', 22),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is dissipation?', 'When energy spreads out into the surroundings, becoming less useful.', 23),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'Calculate the energy transferred by a 2 kW heater in 10 minutes.', '2000 × 600 = 1,200,000 J (1.2 MJ).', 24),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What is a kilowatt-hour used for?', 'Measuring electrical energy used by appliances for billing.', 25),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'How does work done relate to kinetic energy?', 'Work done on an object by a resultant force increases its kinetic energy.', 26),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What happens to the work done when stretching a spring?', 'It is stored as elastic potential energy.', 27),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'Calculate the power when a 50 kg person climbs 3 m in 5 s (g = 10).', 'GPE = 50 × 10 × 3 = 1500 J; P = 1500 ÷ 5 = 300 W.', 28),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'What does a power rating on an appliance tell you?', 'How much energy it transfers per second.', 29),
  ('Physics', 'Edexcel', 'gcse', '8', 'Energy — Forces Doing Work', 'How does thermal insulation reduce energy transfer?', 'It reduces conduction and convection, reducing the rate of heat loss.', 30),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is a resultant force?', 'The single force that has the same effect as all the forces acting on an object.', 1),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How do you calculate the resultant of two forces in the same direction?', 'Add them.', 2),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How do you calculate the resultant of two forces in opposite directions?', 'Subtract the smaller from the larger; the resultant acts in the direction of the larger.', 3),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What happens if the resultant force is zero?', 'The object stays at rest or continues at constant velocity.', 4),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is a contact force?', 'A force that acts when objects are touching, e.g. friction, air resistance, tension and normal contact force.', 5),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is a non-contact force?', 'A force that acts at a distance, e.g. gravity, magnetism and electrostatic force.', 6),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is a free-body force diagram?', 'A diagram showing all the forces acting on a single object, with arrows showing size and direction.', 7),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How can forces be resolved?', 'By splitting a force into two perpendicular components, e.g. horizontal and vertical.', 8),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is a moment?', 'The turning effect of a force: moment = force × perpendicular distance from the pivot.', 9),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is the unit of a moment?', 'Newton metre (N m).', 10),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is the principle of moments?', 'For an object in equilibrium, the sum of clockwise moments equals the sum of anticlockwise moments.', 11),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'A 10 N force acts 0.5 m from a pivot. What is the moment?', '10 × 0.5 = 5 N m.', 12),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How do levers make work easier?', 'They increase the distance from the pivot, so a smaller force can produce the same moment.', 13),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How do gears work?', 'They transmit the rotational effect of forces; a small gear driving a larger gear increases the moment.', 14),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is the normal contact force?', 'The force exerted by a surface on an object, perpendicular to the surface.', 15),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is friction?', 'A force that opposes motion between surfaces in contact.', 16),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is air resistance?', 'A frictional force that opposes an object''s motion through air.', 17),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is tension?', 'The force in a stretched string, rope or cable.', 18),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is equilibrium?', 'When all the forces on an object are balanced, so the resultant force is zero.', 19),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How can a vector diagram show forces in equilibrium?', 'When drawn tip to tail, the forces form a closed shape.', 20),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is upthrust?', 'An upward force exerted by a fluid on an object submerged in it.', 21),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How does a car''s driving force relate to its speed?', 'At constant speed the driving force equals the resistive forces.', 22),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What happens when a skydiver opens a parachute?', 'Air resistance increases, so the skydiver decelerates to a lower terminal velocity.', 23),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is the effect of increasing mass on acceleration for the same force?', 'Acceleration decreases (a = F/m).', 24),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'Calculate the resultant force on a 1000 kg car accelerating at 2 m/s².', 'F = 1000 × 2 = 2000 N.', 25),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is a pivot?', 'The point around which an object turns (the fulcrum).', 26),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'Why is a long spanner easier to use?', 'The force acts further from the pivot, producing a larger moment.', 27),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'What is the centre of mass?', 'The point at which the weight of an object appears to act.', 28),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'When will an object topple?', 'When the line of action of its weight falls outside its base.', 29),
  ('Physics', 'Edexcel', 'gcse', '9', 'Forces and Their Effects', 'How can an object be made more stable?', 'Lowering its centre of mass and widening its base.', 30),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is electric current?', 'The rate of flow of charge: I = Q/t.', 1),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is potential difference?', 'The energy transferred per unit charge between two points: V = E/Q.', 2),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is resistance?', 'How much a component opposes the flow of current: R = V/I.', 3),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is Ohm''s law?', 'The current through a resistor is directly proportional to the potential difference, at constant temperature.', 4),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'Calculate the current when 12 V is applied across a 4 Ω resistor.', 'I = 12 ÷ 4 = 3 A.', 5),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'Calculate the charge that flows when 2 A flows for 30 s.', 'Q = 2 × 30 = 60 C.', 6),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is a series circuit?', 'A circuit where components are connected in a single loop.', 7),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is a parallel circuit?', 'A circuit where components are connected on separate branches.', 8),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What happens to current in a series circuit?', 'It is the same everywhere.', 9),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What happens to potential difference in a series circuit?', 'It is shared between the components.', 10),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What happens to current in a parallel circuit?', 'It is shared between the branches; the total current equals the sum of the branch currents.', 11),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What happens to potential difference in a parallel circuit?', 'It is the same across each branch.', 12),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'How do you calculate total resistance in series?', 'Add the resistances: R_total = R₁ + R₂.', 13),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What happens to total resistance when resistors are added in parallel?', 'It decreases, and is less than the smallest individual resistance.', 14),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'How is an ammeter connected?', 'In series with the component.', 15),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'How is a voltmeter connected?', 'In parallel across the component.', 16),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the I–V graph for a fixed resistor?', 'A straight line through the origin.', 17),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the I–V graph for a filament lamp?', 'A curve that gets less steep, because resistance increases as the filament heats up.', 18),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the I–V graph for a diode?', 'Current flows in one direction only, after a small threshold voltage.', 19),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'How does the resistance of a thermistor change?', 'It decreases as temperature increases.', 20),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'How does the resistance of an LDR change?', 'It decreases as light intensity increases.', 21),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is electrical power?', 'P = IV = I²R.', 22),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'Calculate the power of a lamp with 230 V and 0.5 A.', 'P = 230 × 0.5 = 115 W.', 23),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the equation for energy transferred electrically?', 'E = IVt (or E = QV).', 24),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the difference between AC and DC?', 'AC changes direction regularly; DC flows in one direction only.', 25),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the UK mains supply?', 'AC at 230 V and 50 Hz.', 26),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What are the three wires in a UK plug?', 'Live (brown), neutral (blue) and earth (green and yellow).', 27),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the purpose of the earth wire?', 'It stops the casing becoming live, preventing electric shocks if there is a fault.', 28),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'What is the purpose of a fuse?', 'It melts and breaks the circuit if the current is too high, protecting the appliance and preventing fires.', 29),
  ('Physics', 'Edexcel', 'gcse', '10', 'Electricity and Circuits', 'Why does a current in a resistor cause heating?', 'Electrons collide with ions in the lattice, transferring energy and making them vibrate more.', 30),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is static electricity?', 'A build-up of electric charge on the surface of an insulator.', 1),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How does an object become charged by friction?', 'Electrons are transferred from one material to another when they are rubbed together.', 2),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What charge does an object get if it gains electrons?', 'Negative.', 3),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What charge does an object get if it loses electrons?', 'Positive.', 4),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'Why can only electrons move when objects are charged?', 'Protons are fixed in the nucleus; electrons are on the outside and can be transferred.', 5),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What happens when two like charges are brought together?', 'They repel.', 6),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What happens when two opposite charges are brought together?', 'They attract.', 7),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'Why does a charged balloon stick to a wall?', 'The balloon induces an opposite charge on the wall''s surface, so they attract.', 8),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is an electric field?', 'A region where a charged object experiences a force.', 9),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is the direction of an electric field?', 'The direction of the force on a positive charge: away from positive charges and towards negative charges.', 10),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What does a stronger electric field look like?', 'Field lines are closer together.', 11),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What happens when a charged object is near an earthed conductor?', 'Electrons flow to or from the earth, discharging the object.', 12),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is a spark?', 'A discharge of static electricity through the air, when the potential difference is high enough.', 13),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'Why is static electricity dangerous when refuelling aircraft?', 'Fuel flowing through pipes can build up charge, which could cause a spark and ignite the fuel.', 14),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How is static electricity made safe when refuelling?', 'The fuel tank is earthed with a bonding line so charge can flow safely to earth.', 15),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How is static electricity used in paint spraying?', 'Paint droplets are charged, and the object is oppositely charged, so the paint is attracted evenly.', 16),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How is static electricity used in photocopiers?', 'A charged drum attracts toner in the pattern of the image, which is transferred to paper.', 17),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How is static electricity used in inkjet printers?', 'Ink droplets are charged and deflected by charged plates to direct them onto the paper.', 18),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How can static electricity cause shocks?', 'Charge builds up on a person, then flows through them when they touch a conductor.', 19),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is earthing?', 'Connecting an object to the ground so charge can flow away safely.', 20),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'Why are insulators able to hold static charge?', 'Charge can''t move through them, so it stays where it is.', 21),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'Why do metals not usually build up static charge?', 'Charge flows through them to earth.', 22),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is induction of charge?', 'Charges in an object are rearranged by a nearby charged object without contact.', 23),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How does a gold-leaf electroscope show charge?', 'Charge spreads to the leaves, which repel each other and spread apart.', 24),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What happens to a stream of water near a charged rod?', 'It bends towards the rod because of induced charges.', 25),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What happens when a polythene rod is rubbed with a cloth?', 'Electrons move from the cloth to the rod, so the rod becomes negative.', 26),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What happens when an acetate rod is rubbed with a cloth?', 'Electrons move from the rod to the cloth, so the rod becomes positive.', 27),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is lightning?', 'A large discharge of static electricity between clouds and the ground.', 28),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'How do dust precipitators work?', 'Smoke particles are charged and attracted to oppositely charged plates, removing them from chimney gases.', 29),
  ('Physics', 'Edexcel', 'gcse', '11', 'Static Electricity', 'What is the unit of charge?', 'The coulomb (C).', 30),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is a magnetic field?', 'A region where a magnetic material or magnet experiences a force.', 1),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is the direction of a magnetic field line?', 'From the north pole to the south pole.', 2),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What happens when like magnetic poles are brought together?', 'They repel.', 3),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What happens when unlike magnetic poles are brought together?', 'They attract.', 4),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is a permanent magnet?', 'A magnet that produces its own magnetic field all the time.', 5),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is an induced magnet?', 'A material that becomes magnetic when placed in a magnetic field, and loses it when removed.', 6),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'Name three magnetic materials.', 'Iron, nickel and cobalt (and steel).', 7),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'How can you plot a magnetic field?', 'Using a plotting compass placed around the magnet and marking the direction of the needle.', 8),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is the Earth''s magnetic field evidence?', 'A compass points north because the Earth has a magnetic field; its core is magnetic.', 9),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is the magnetic field around a current-carrying wire?', 'Concentric circles around the wire.', 10),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'How can you find the direction of the field around a wire?', 'Using the right-hand grip rule: thumb points in the current direction and fingers curl in the field direction.', 11),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is a solenoid?', 'A coil of wire that produces a magnetic field when current flows through it, similar to a bar magnet.', 12),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'How can the strength of a solenoid be increased?', 'More turns, a larger current, and adding an iron core.', 13),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is an electromagnet?', 'A solenoid with an iron core, which can be switched on and off.', 14),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'Give two uses of electromagnets.', 'Scrap yard cranes, electric bells, relays and door locks.', 15),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is the motor effect?', 'A current-carrying wire in a magnetic field experiences a force.', 16),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is Fleming''s left-hand rule?', 'First finger = field, second finger = current, thumb = motion (force).', 17),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is the equation for the force on a wire in a magnetic field?', 'F = B × I × l.', 18),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is magnetic flux density?', 'A measure of the strength of a magnetic field, measured in tesla (T).', 19),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'Calculate the force on a 0.5 m wire carrying 2 A in a 0.1 T field.', 'F = 0.1 × 2 × 0.5 = 0.1 N.', 20),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'How does an electric motor work?', 'Current in a coil in a magnetic field creates forces on opposite sides in opposite directions, making the coil rotate.', 21),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is the role of the split-ring commutator?', 'It reverses the current every half turn, so the coil keeps rotating in the same direction.', 22),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'How can the speed of a motor be increased?', 'Increase the current, use a stronger magnet, or add more turns to the coil.', 23),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'How do loudspeakers work?', 'Alternating current in a coil in a magnetic field makes the coil and cone vibrate, producing sound.', 24),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'When is the force on a wire zero?', 'When the wire is parallel to the magnetic field.', 25),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'When is the force on a wire greatest?', 'When the wire is at right angles to the magnetic field.', 26),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'How can the direction of the force be reversed?', 'Reverse the current or the magnetic field.', 27),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'Why is iron used as a core in electromagnets?', 'It is easily magnetised and demagnetised, and concentrates the magnetic field.', 28),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'What is a uniform magnetic field?', 'A field with the same strength and direction everywhere, shown by parallel, equally spaced lines.', 29),
  ('Physics', 'Edexcel', 'gcse', '12', 'Magnetism and the Motor Effect', 'Where is a bar magnet''s field strongest?', 'At the poles.', 30),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is electromagnetic induction?', 'Generating a potential difference in a conductor when it moves relative to a magnetic field.', 1),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'How can the induced potential difference be increased?', 'Moving the magnet or wire faster, using a stronger magnet, or using more turns on the coil.', 2),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'When is a current induced?', 'When the conductor is part of a complete circuit.', 3),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the generator effect?', 'Producing electricity by electromagnetic induction.', 4),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'How does an alternator work?', 'A coil rotates in a magnetic field, inducing an alternating current, with slip rings and brushes.', 5),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'How does a dynamo work?', 'A coil rotates in a magnetic field, inducing a direct current, using a split-ring commutator.', 6),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'How does a microphone work?', 'Sound waves make a diaphragm and coil vibrate in a magnetic field, inducing a current that matches the sound.', 7),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is a transformer?', 'A device that changes the size of an alternating voltage.', 8),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'How does a transformer work?', 'AC in the primary coil creates a changing magnetic field in the iron core, inducing an AC voltage in the secondary coil.', 9),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'Why do transformers only work with AC?', 'A changing magnetic field is needed to induce a voltage; DC produces a constant field.', 10),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is a step-up transformer?', 'A transformer with more turns on the secondary coil, increasing the voltage.', 11),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is a step-down transformer?', 'A transformer with fewer turns on the secondary coil, decreasing the voltage.', 12),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the transformer equation?', 'Vp/Vs = Np/Ns.', 13),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'A transformer has 100 primary turns and 500 secondary turns. The input is 20 V. What is the output?', 'Vs = 20 × 500/100 = 100 V.', 14),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the power equation for an ideal transformer?', 'Vp × Ip = Vs × Is.', 15),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the National Grid?', 'A network of cables and transformers that distributes electricity across the country.', 16),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'Why is electricity transmitted at high voltage?', 'High voltage means low current, reducing energy lost as heat in the cables.', 17),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'Where are step-up transformers used in the National Grid?', 'At power stations, to increase the voltage for transmission.', 18),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'Where are step-down transformers used in the National Grid?', 'Near homes and businesses, to reduce the voltage to a safe level (230 V).', 19),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the direction of an induced current?', 'It creates a magnetic field that opposes the change that caused it.', 20),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What happens if a magnet is held stationary inside a coil?', 'No current is induced because there is no relative movement.', 21),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What happens if a magnet is pushed into a coil then pulled out?', 'A current is induced in one direction, then in the opposite direction.', 22),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the role of the iron core in a transformer?', 'It links the magnetic field between the primary and secondary coils.', 23),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'Why do transformers get warm?', 'Some energy is wasted as heat in the coils and the core.', 24),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is a slip ring?', 'A connection in an alternator that allows current to flow from the rotating coil while keeping it AC.', 25),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'How does the frequency of AC from a generator relate to rotation speed?', 'Faster rotation gives a higher frequency.', 26),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the output of an alternator shown on an oscilloscope?', 'A sine wave (alternating voltage).', 27),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the output of a dynamo shown on an oscilloscope?', 'A voltage that varies but stays positive (direct).', 28),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'How are power stations connected to homes?', 'Through the National Grid: power station → step-up transformer → transmission cables → step-down transformer → homes.', 29),
  ('Physics', 'Edexcel', 'gcse', '13', 'Electromagnetic Induction', 'What is the efficiency of a transformer if the input is 100 W and the output is 95 W?', '95%.', 30),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is density?', 'Mass per unit volume: ρ = m/V.', 1),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the unit of density?', 'kg/m³ (or g/cm³).', 2),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'Calculate the density of a 200 g block with volume 100 cm³.', '200 ÷ 100 = 2 g/cm³.', 3),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'How can the density of an irregular object be found?', 'Measure its mass with a balance and its volume by displacement of water in a measuring cylinder.', 4),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the particle arrangement in a solid?', 'Particles are closely packed in a regular pattern, vibrating about fixed positions.', 5),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the particle arrangement in a liquid?', 'Particles are close together but randomly arranged and can move past each other.', 6),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the particle arrangement in a gas?', 'Particles are far apart, randomly arranged and move quickly in all directions.', 7),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'Why are gases less dense than solids?', 'The particles are much further apart.', 8),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is internal energy?', 'The total kinetic and potential energy of all the particles in a system.', 9),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What happens to internal energy when a substance is heated?', 'It increases, either raising the temperature or changing the state.', 10),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is specific heat capacity?', 'The energy needed to raise the temperature of 1 kg of a substance by 1 °C.', 11),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the equation for specific heat capacity?', 'ΔQ = m × c × Δθ.', 12),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'Calculate the energy needed to heat 2 kg of water by 10 °C (c = 4200 J/kg°C).', '2 × 4200 × 10 = 84,000 J.', 13),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is specific latent heat?', 'The energy needed to change the state of 1 kg of a substance without a change in temperature.', 14),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the equation for specific latent heat?', 'Q = m × L.', 15),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the specific latent heat of fusion?', 'The energy needed to change 1 kg from solid to liquid.', 16),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the specific latent heat of vaporisation?', 'The energy needed to change 1 kg from liquid to gas.', 17),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'Why does temperature stay constant during a change of state?', 'The energy is used to break bonds between particles, not to increase kinetic energy.', 18),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is melting?', 'Changing from solid to liquid.', 19),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is evaporation?', 'Changing from liquid to gas at the surface of a liquid, below its boiling point.', 20),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is condensation?', 'Changing from gas to liquid.', 21),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is sublimation?', 'Changing directly from solid to gas.', 22),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'Are changes of state physical or chemical?', 'Physical, because they are reversible and the substance keeps its chemical properties.', 23),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'Is mass conserved when a substance changes state?', 'Yes.', 24),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'How do gas particles exert pressure?', 'They collide with the walls of the container, exerting a force.', 25),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What happens to gas pressure when temperature increases (constant volume)?', 'Pressure increases because particles move faster and collide more often and with more force.', 26),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is absolute zero?', '−273 °C (0 K), the lowest possible temperature, where particles have the minimum kinetic energy.', 27),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'Convert 27 °C to kelvin.', '27 + 273 = 300 K.', 28),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What happens to gas pressure when volume decreases (constant temperature)?', 'Pressure increases because particles hit the walls more often.', 29),
  ('Physics', 'Edexcel', 'gcse', '14', 'Particle Model', 'What is the equation linking pressure and volume at constant temperature?', 'p₁V₁ = p₂V₂.', 30),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is elastic deformation?', 'When an object returns to its original shape after the force is removed.', 1),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is inelastic (plastic) deformation?', 'When an object doesn''t return to its original shape after the force is removed.', 2),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is Hooke''s law?', 'The extension of a spring is directly proportional to the force applied, up to the limit of proportionality.', 3),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the equation for Hooke''s law?', 'F = k × x.', 4),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the spring constant?', 'The force needed to stretch a spring by 1 m, measured in N/m.', 5),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Calculate the force needed to stretch a spring with k = 50 N/m by 0.2 m.', '50 × 0.2 = 10 N.', 6),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the limit of proportionality?', 'The point beyond which extension is no longer proportional to force.', 7),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the energy stored in a stretched spring?', 'E = ½kx² (elastic potential energy).', 8),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Calculate the energy stored in a spring with k = 100 N/m stretched 0.1 m.', '½ × 100 × 0.1² = 0.5 J.', 9),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What does the gradient of a force–extension graph show?', 'The spring constant.', 10),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What does the area under a force–extension graph show?', 'The work done (energy stored) in stretching.', 11),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'How can you investigate the extension of a spring?', 'Hang masses on a spring, measure the extension with a ruler each time, and plot force against extension.', 12),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Why do you need more than one force to stretch an object?', 'One force would just move the object; two forces in opposite directions are needed to stretch, squash or bend it.', 13),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is pressure?', 'Force per unit area: p = F/A.', 14),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the unit of pressure?', 'The pascal (Pa), equal to 1 N/m².', 15),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Calculate the pressure when a 500 N force acts on 0.1 m².', '500 ÷ 0.1 = 5000 Pa.', 16),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Why do snowshoes help you walk on snow?', 'They spread the weight over a larger area, reducing pressure.', 17),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Why are knives sharp?', 'A small area produces a large pressure for the same force.', 18),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'How does pressure in a liquid change with depth?', 'It increases with depth.', 19),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the equation for pressure in a liquid?', 'p = h × ρ × g.', 20),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Why do dams get thicker at the bottom?', 'Water pressure is greater at greater depth.', 21),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is upthrust?', 'The upward force on an object in a fluid, caused by the greater pressure below it than above.', 22),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'When does an object float?', 'When the upthrust equals the object''s weight.', 23),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Why do objects less dense than water float?', 'They displace their own weight of water before becoming fully submerged.', 24),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is atmospheric pressure?', 'The pressure caused by the weight of air above a surface.', 25),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'How does atmospheric pressure change with height?', 'It decreases as altitude increases, because there is less air above.', 26),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the effect of pressure on a gas?', 'Gas pressure acts in all directions at right angles to surfaces.', 27),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'Why are hydraulic systems useful?', 'Liquids are incompressible, so a small force on a small piston creates a large force on a larger piston.', 28),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is compression?', 'When forces squash an object, making it shorter.', 29),
  ('Physics', 'Edexcel', 'gcse', '15', 'Forces and Matter', 'What is the difference between a spring and a rubber band in stretching?', 'A spring obeys Hooke''s law up to a limit; a rubber band doesn''t have a linear force–extension graph.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Physics' AND exam_board = 'Edexcel' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
